<?php $title = 'Produk'; require __DIR__ . '/layout.php'; ?><section class="page-head"><div><p class="eyebrow">DATA MASTER</p><h1>Produk</h1><p>Kelola katalog dan stok barang koperasi.</p></div></section><section class="grid-2"><form class="panel form-panel" method="post" action="/kelompok-5/produk"><h2>Tambah produk</h2><label>ID kategori<input type="number" name="id_kategori" required></label><label>Nama produk<input name="nama_produk" required></label><label>Harga<input type="number" name="harga" min="0" required></label><label>Stok<input type="number" name="stok" min="0" required></label><button class="button" type="submit">Simpan produk</button></form><section class="panel"><div class="panel-head"><h2>Daftar produk</h2><span class="badge"><?= count($products ?? []) ?> item</span></div><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach ($products ?? [] as $row): ?><tr><td><?= htmlspecialchars($row['nama_produk']) ?></td><td>Rp <?= number_format($row['harga'], 0, ',', '.') ?></td><td><?= htmlspecialchars($row['stok']) ?></td><td><form method="post" action="/kelompok-5/produk/delete" onsubmit="return confirmDelete()"><input type="hidden" name="id" value="<?= $row['id_produk'] ?>"><button class="link danger" type="submit">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></section><?php require __DIR__ . '/footer.php'; ?>